GlobalTagDto GlobalTagDto::fromJson(const json &j) {
  GlobalTagDto globalTag;
  globalTag.name = StringUtils::getStringOr(j, "name");
  globalTag.validity = j.value<uint64_t>("validity", 0);
  globalTag.description = StringUtils::getStringOr(j, "description");
  globalTag.release = StringUtils::getStringOr(j, "release");
  if (j.contains(std::string{"insertionTime"}))
    globalTag.insertionTime = j.value("insertionTime", "");
  if (j.contains(std::string{"snapshotTime"}))
    globalTag.snapshotTime = j.value("snapshotTime", "");
  globalTag.scenario = StringUtils::getStringOr(j, "scenario");
  globalTag.workflow = StringUtils::getStringOr(j, "workflow");
  globalTag.type = StringUtils::getStringOr(j, "type");
  globalTag.snapshotTimeMilli = j.value("snapshotTimeMilli", int64_t{0});
  globalTag.insertionTimeMilli = j.value("insertionTimeMilli", int64_t{0});
  return globalTag;
}
